{"file_path":"./src/parse.js","content":"/**
 * Parsing of the three-document standard input format.
 */

export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }
  return lines
}

export function parseDocuments(text) {
  const lines = splitLines(text)
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }
  if (parts.length !== 3) {
    throw new Error('expected three parts separated by %%%')
  }
  return parts
}
"}

