{"file_path":"./src/lcs.js","content":"/**
 * Longest common subsequence of two line arrays, with a specific
 * tie-breaking rule so that among equally long subsequences we pick the
 * one whose matches occur earliest.
 */

export function computeMatches(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:]
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)

  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        dp[i][j] = 1 + dp[i + 1][j + 1]
      } else {
        const advanceBase = dp[i + 1][j]
        const advanceSide = dp[i][j + 1]
        dp[i][j] = advanceBase >= advanceSide ? advanceBase : advanceSide
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const advanceBase = dp[i + 1][j]
      const advanceSide = dp[i][j + 1]
      if (advanceBase >= advanceSide) {
        i++
      } else {
        j++
      }
    }
  }

  return matches
}
"}

