{"file_path":"./src/diff.js","content":"/**
 * Turn a base/side line-array pair into a list of changes: runs of base
 * lines replaced by runs of the side's lines, derived from the matches an
 * LCS computation finds between them.
 */

import { computeMatches } from './lcs.js'

export function computeChanges(base, side, label) {
  const matches = computeMatches(base, side)
  const changes = []

  let bStart = 0
  let sStart = 0

  const flush = (bEnd, sEnd) => {
    if (bStart < bEnd || sStart < sEnd) {
      changes.push({ side: label, bStart, bEnd, sStart, sEnd })
    }
  }

  for (const [bi, sj] of matches) {
    flush(bi, sj)
    bStart = bi + 1
    sStart = sj + 1
  }
  flush(base.length, side.length)

  return changes
}
"}

