{"file_path":"./src/merge.js","content":"/**
 * Grouping of mine's and theirs's changes against the base into regions,
 * and resolving each region to stable/mine/theirs/both lines or a
 * conflict.
 */

import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

function buildSideLines(base, side, region, changes) {
  const result = []
  let pos = region.bStart
  for (const c of changes) {
    for (let k = pos; k < c.bStart; k++) result.push(base[k])
    for (let k = c.sStart; k < c.sEnd; k++) result.push(side[k])
    pos = c.bEnd
  }
  for (let k = pos; k < region.bEnd; k++) result.push(base[k])
  return result
}

function groupRegions(changes) {
  const sorted = [...changes].sort((a, b) => {
    if (a.bStart !== b.bStart) return a.bStart - b.bStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  for (const c of sorted) {
    const last = regions[regions.length - 1]
    if (last && c.bStart <= last.bEnd) {
      last.bEnd = Math.max(last.bEnd, c.bEnd)
      last.changes.push(c)
    } else {
      regions.push({ bStart: c.bStart, bEnd: c.bEnd, changes: [c] })
    }
  }
  return regions
}

function resolveRegion(base, mine, theirs, region) {
  const baseLines = base.slice(region.bStart, region.bEnd)
  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')

  const mineLines = buildSideLines(base, mine, region, mineChanges)
  const theirsLines = buildSideLines(base, theirs, region, theirsChanges)

  if (arraysEqual(mineLines, theirsLines)) {
    if (arraysEqual(mineLines, baseLines)) {
      return { type: 'stable', lines: mineLines }
    }
    return { type: 'both', lines: mineLines }
  }
  if (arraysEqual(mineLines, baseLines)) {
    return { type: 'theirs', lines: theirsLines }
  }
  if (arraysEqual(theirsLines, baseLines)) {
    return { type: 'mine', lines: mineLines }
  }
  return { type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines }
}

/**
 * Returns an ordered list of resolved segments covering the whole base
 * document, each either a resolved run of lines (stable/mine/theirs/both)
 * or a conflict.
 */
export function mergeDocuments(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine, 'mine')
  const theirsChanges = computeChanges(base, theirs, 'theirs')
  const regions = groupRegions([...mineChanges, ...theirsChanges])

  const segments = []
  let pos = 0
  for (const region of regions) {
    if (pos < region.bStart) {
      segments.push({ type: 'stable', lines: base.slice(pos, region.bStart) })
    }
    segments.push(resolveRegion(base, mine, theirs, region))
    pos = region.bEnd
  }
  if (pos < base.length) {
    segments.push({ type: 'stable', lines: base.slice(pos, base.length) })
  }

  return segments
}
"}

